INSERT INTO breach_incidents (organization_id, title, description, breach_incident_severity, breach_incident_status, detected_at, ndpc_notification_deadline, ndpc_notified_at, affected_individuals_count, data_types_affected, breach_cause, remediation_actions, ndpc_reference_number) VALUES
(1, 'Unauthorized Database Access - Customer PII Exposed', 'An external attacker gained unauthorized access to the customer database via SQL injection, exposing personal data of approximately 15,000 customers including names, emails, BVN numbers and addresses.', 'critical', 'ndpc_notified', NOW() - INTERVAL '5 days', NOW() - INTERVAL '2 days', NOW() - INTERVAL '2 days', 15000, '["name","email","bvn","address","phone"]', 'SQL injection vulnerability in legacy authentication module', 'Patched SQL injection vulnerability, rotated all database credentials, notified affected customers, engaged forensic investigation firm', 'NDPC/BR/2026/001'),
(2, 'Employee Laptop Theft - Customer Records', 'A company laptop containing unencrypted customer health records was stolen from an employee vehicle. The laptop contained records of approximately 3,200 policyholders.', 'high', 'individuals_notified', NOW() - INTERVAL '10 days', NOW() - INTERVAL '7 days', NOW() - INTERVAL '7 days', 3200, '["name","health_records","nin","address"]', 'Unencrypted laptop stolen from employee vehicle', 'Implemented mandatory full-disk encryption, remote wipe executed, affected individuals notified, police report filed', 'NDPC/BR/2026/002'),
(3, 'Third-Party API Data Leak', 'A misconfigured API endpoint at a third-party payment processor exposed transaction data for 8,500 customers over a 48-hour window before discovery.', 'high', 'contained', NOW() - INTERVAL '3 days', NOW() + INTERVAL '1 day', NULL, 8500, '["name","account_number","transaction_history"]', 'Misconfigured API authentication at third-party processor', 'API endpoint secured, third-party contract reviewed, data minimization measures implemented', NULL),
(4, 'Phishing Attack - Staff Credentials Compromised', 'A targeted phishing campaign compromised credentials of 3 staff members, potentially exposing access to customer energy consumption data.', 'medium', 'assessing', NOW() - INTERVAL '1 day', NOW() + INTERVAL '2 days', NULL, 500, '["name","address","consumption_data"]', 'Phishing email targeting finance department staff', 'Compromised accounts suspended, MFA enforced, security awareness training scheduled', NULL),
(5, 'Accidental Data Disclosure via Email', 'Customer data was accidentally included in a bulk email sent to wrong recipients due to a spreadsheet error.', 'low', 'resolved', NOW() - INTERVAL '20 days', NOW() - INTERVAL '17 days', NOW() - INTERVAL '17 days', 125, '["name","email","policy_number"]', 'Human error - wrong spreadsheet attached to bulk email', 'Affected customers notified, email recall attempted, process review completed, staff retrained', 'NDPC/BR/2026/003');
