INSERT INTO dpo_reports (organization_id, dpo_appointment_id, report_period_start, report_period_end, status, activities_summary, violations_identified, dsars_handled, training_conducted, privacy_notices_review, recommendations, submitted_at) VALUES
(1, 1, NOW() - INTERVAL '6 months', NOW() - INTERVAL '3 months', 'submitted', 'Conducted quarterly privacy audit, reviewed 3 new data processing agreements, updated privacy notices for mobile banking app, coordinated response to 2 DSAR requests, delivered data protection training to 150 staff members.', 2, 8, 3, 'Privacy notices updated to reflect new mobile banking features and NDPA 2023 requirements', 'Recommend implementing automated DSAR tracking system, enhance third-party processor audit program', NOW() - INTERVAL '2 months'),
(2, 2, NOW() - INTERVAL '6 months', NOW() - INTERVAL '3 months', 'submitted', 'Reviewed NIN linkage compliance, conducted privacy impact assessment for new 5G rollout, handled 15 DSAR requests, updated data retention schedules, coordinated with NCC on lawful interception compliance.', 1, 15, 5, 'Privacy notices updated for 5G services and new data processing activities', 'Recommend enhanced encryption for CDR storage, implement automated data deletion workflows', NOW() - INTERVAL '2 months'),
(3, 3, NOW() - INTERVAL '3 months', NOW(), 'draft', 'Ongoing review of patient data localisation compliance, coordinating with healthcare providers on EMR data standards, reviewing cross-border data sharing with international health organizations.', 3, 5, 2, 'Privacy notices under review for telemedicine services', 'Urgent: implement data localisation controls for telemedicine platform, review international health data sharing agreements', NULL),
(1, 1, NOW() - INTERVAL '3 months', NOW(), 'submitted', 'Responded to data breach incident (NDPC/BR/2026/001), coordinated forensic investigation, notified 15,000 affected customers, implemented enhanced security controls, submitted breach notification to NDPC.', 5, 12, 8, 'Privacy notices updated post-breach to reflect enhanced security measures', 'Implement zero-trust architecture, enhance third-party security assessments, conduct annual penetration testing', NOW() - INTERVAL '1 week');
INSERT INTO adequacy_determinations (country_code, country_name, status, determination_date, review_date, ndpc_decision, conditions, applicable_sectors, is_active) VALUES
('GB', 'United Kingdom', 'adequate', NOW() - INTERVAL '2 years', NOW() + INTERVAL '1 year', 'The UK GDPR and Data Protection Act 2018 provide adequate protection equivalent to NDPA 2023 standards', 'Annual review required, monitoring of UK post-Brexit data protection developments', '["all"]', true),
('EU', 'European Union', 'adequate', NOW() - INTERVAL '3 years', NOW() + INTERVAL '6 months', 'EU GDPR provides adequate protection. Nigerian organizations may transfer data to EU member states without additional safeguards', 'Quarterly monitoring of CJEU decisions affecting data protection adequacy', '["all"]', true),
('US', 'United States', 'conditional', NOW() - INTERVAL '1 year', NOW() + INTERVAL '3 months', 'Transfers permitted only to US entities participating in the US-Nigeria Data Bridge framework or with appropriate safeguards (SCCs)', 'Must use Standard Contractual Clauses or Binding Corporate Rules. Financial sector transfers require CBN approval', '["banking","fintech","insurance"]', true),
('ZA', 'South Africa', 'adequate', NOW() - INTERVAL '18 months', NOW() + INTERVAL '18 months', 'POPIA provides adequate protection. ECOWAS data sharing framework applies', 'Monitor POPIA enforcement developments, annual review', '["all"]', true),
('CN', 'China', 'inadequate', NOW() - INTERVAL '6 months', NOW() + INTERVAL '6 months', 'China PIPL does not provide adequate protection equivalent to NDPA 2023. Transfers prohibited without explicit NDPC approval', 'Case-by-case approval required from NDPC. Enhanced due diligence mandatory', '["none"]', true),
('KE', 'Kenya', 'adequate', NOW() - INTERVAL '1 year', NOW() + INTERVAL '1 year', 'Kenya Data Protection Act 2019 provides adequate protection within ECOWAS framework', 'Annual review, monitoring of Kenya DPA enforcement', '["all"]', true),
('IN', 'India', 'conditional', NOW() - INTERVAL '3 months', NOW() + INTERVAL '9 months', 'India DPDP Act 2023 under review. Conditional adequacy pending full implementation assessment', 'Transfers permitted with Standard Contractual Clauses pending full adequacy determination', '["technology","fintech"]', true),
('AE', 'United Arab Emirates', 'conditional', NOW() - INTERVAL '8 months', NOW() + INTERVAL '4 months', 'UAE PDPL provides partial adequacy. Financial sector transfers require CBN and CBUAE coordination', 'Enhanced due diligence for financial data transfers, coordination with CBN required', '["banking","insurance","fintech"]', true);
