INSERT INTO privacy_notices (organization_id, notice_title, version, status, language, content, effective_date, review_date) VALUES
(1, 'First Bank Customer Privacy Notice', '3.2', 'published', 'en', 'This Privacy Notice explains how First Bank of Nigeria Plc ("First Bank", "we", "us") collects, uses, stores and protects your personal data in accordance with the Nigeria Data Protection Act 2023 (NDPA) and CBN regulations. We collect your data for account management, KYC compliance, fraud prevention, and service delivery. Your data is stored securely within Nigeria and shared only with regulatory authorities as required by law. You have rights to access, correct, delete and object to processing of your data. Contact our DPO at dpo@firstbank.com.ng for any privacy concerns.', NOW() - INTERVAL '3 months', NOW() + INTERVAL '9 months'),
(2, 'MTN Nigeria Subscriber Privacy Policy', '2.1', 'published', 'en', 'MTN Nigeria Communications Plc is committed to protecting your privacy. This policy describes how we collect and use your personal data including subscriber information, call records, location data and usage patterns. We process your data to provide telecommunications services, comply with NCC regulations, and improve our network. Your data is retained as required by NCC regulations. You have the right to access your data, request corrections, and lodge complaints with the NDPC. Contact privacy@mtn.com.ng for privacy inquiries.', NOW() - INTERVAL '6 months', NOW() + INTERVAL '6 months'),
(3, 'NHIA Enrollee Data Privacy Notice', '1.5', 'published', 'en', 'The National Health Insurance Authority (NHIA) processes your health and personal data to administer the National Health Insurance Scheme. This includes your health records, treatment history, and insurance claims. Your data is processed under legal obligation and vital interests basis. Health data is stored securely within Nigeria and shared only with accredited healthcare providers and FMOH as required. Contact our DPO at dpo@nhia.gov.ng for privacy rights requests.', NOW() - INTERVAL '1 year', NOW() + INTERVAL '6 months'),
(4, 'NERC Consumer Data Privacy Notice', '1.0', 'draft', 'en', 'The Nigerian Electricity Regulatory Commission (NERC) processes electricity consumer data including consumption records, meter data, and account information to regulate the electricity sector and ensure fair billing. Data is processed under legal obligation. Contact dpo@nerc.gov.ng for privacy inquiries.', NULL, NOW() + INTERVAL '3 months'),
(5, 'NAICOM Policyholder Privacy Notice', '2.0', 'published', 'en', 'The National Insurance Commission (NAICOM) processes policyholder data to regulate the insurance industry and protect policyholder interests. We process your insurance records, claims data, and personal information under legal obligation and contract. Your data is retained for 10 years as required by the Insurance Act. Contact dpo@naicom.gov.ng for privacy rights.', NOW() - INTERVAL '4 months', NOW() + INTERVAL '8 months');
