INSERT INTO automated_decision_records (organization_id, system_name, decision_type, data_subject_ref, decision_outcome, logic_explanation, human_review_available, human_review_requested, objection_raised) VALUES
(1, 'CBN Credit Scoring Engine v3.2', 'credit_assessment', 'CUST-2024-001234', 'Credit limit set at NGN 500,000 based on risk score of 72/100', 'Score computed from: payment history (35%), credit utilization (30%), account age (15%), credit mix (10%), new inquiries (10%). Score of 72 indicates moderate-good creditworthiness.', true, false, false),
(1, 'AML Transaction Monitoring System', 'fraud_detection', 'ACCT-2024-056789', 'Transaction flagged for manual review - unusual pattern detected', 'Rule triggered: Transaction amount NGN 4.5M exceeds 3x average monthly transaction. Geographic anomaly: transaction initiated from IP in United Kingdom. Velocity check: 5 transactions in 2 hours.', true, true, false),
(2, 'NCC Network Quality Optimizer', 'service_quality', 'SUB-2024-789012', 'Data throttling applied to subscriber - fair usage policy triggered', 'Subscriber consumed 95% of monthly 50GB allocation in 18 days. Automated throttling to 1Mbps applied per NCC Fair Usage Policy. Full speed restored on billing cycle reset.', true, false, false),
(3, 'NHIA Claims Processing AI', 'insurance_claim', 'CLAIM-2024-345678', 'Claim approved for NGN 125,000 - within standard treatment protocol', 'Diagnosis code ICD-10 J18.9 (Pneumonia) matches approved treatment protocol. Hospital is NHIA-accredited. Claim amount within NGN 150,000 threshold for automated approval. No fraud indicators detected.', true, false, false),
(5, 'NAICOM Fraud Detection Engine', 'fraud_detection', 'CLAIM-2024-901234', 'Insurance claim flagged for investigation - fraud indicators detected', 'Multiple fraud indicators: (1) Claim submitted within 30 days of policy inception, (2) Claim amount equals policy sum insured, (3) Claimant has 2 prior claims in 12 months, (4) Vehicle registration mismatch detected.', true, true, true),
(6, 'CBN Open Banking Risk Engine', 'consent_decision', 'CONS-2024-567890', 'Third-party access request approved with enhanced monitoring', 'Fintech entity is CBN-licensed, NDPA-compliant, data minimization principles met. Access granted for 90 days with monthly review. Enhanced monitoring flag set due to cross-border data element.', true, false, false),
(1, 'Loan Origination System v2.1', 'loan_decision', 'CUST-2024-234567', 'Mortgage application declined - debt-to-income ratio exceeds threshold', 'Automated decline: DTI ratio of 52% exceeds CBN maximum of 40% for mortgage products. Monthly obligations NGN 185,000 against verified income of NGN 356,000. Applicant notified of right to human review.', true, true, false),
(4, 'Smart Grid Load Management AI', 'service_interruption', 'METER-2024-890123', 'Scheduled load shedding applied to zone 3 consumers', 'Grid frequency dropped to 49.2Hz (below 49.5Hz threshold). Automated load shedding activated for non-critical zones. Zone 3 selected based on: lowest priority classification, fewest medical/critical facilities, 4-hour rotation schedule.', true, false, false);
