('DSAR Response Time', 'all', 30, 'days', 'warning', true, 'Maximum time to respond to a Data Subject Access Request', 'NDPA 2023 Section 34'),
('Privacy Notice Update Frequency', 'all', 365, 'days', 'warning', true, 'Maximum days between privacy notice reviews', 'NDPA 2023 Section 24'),
('DPO Training Hours', 'all', 40, 'hours_per_year', 'warning', true, 'Minimum annual training hours for Data Protection Officers', 'NDPC DPO Guidelines 2024'),
('Data Retention Compliance Rate', 'all', 95, 'percent', 'warning', true, 'Minimum percentage of data assets with compliant retention policies', 'NDPA 2023 Section 26'),
('KYC Completion Rate', 'banking', 100, 'percent', 'critical', true, 'All banking customers must complete KYC verification', 'CBN KYC/AML/CFT Regulations 2023'),
('AML Reporting Timeliness', 'banking', 24, 'hours', 'critical', true, 'Maximum time to file STR after suspicious transaction detection', 'EFCC Act 2004 and NFIU Guidelines'),
('NIN Linkage Rate', 'telecom', 100, 'percent', 'critical', true, 'All SIM cards must be linked to NIN', 'NCC SIM Registration Regulations 2022'),
('Data Localisation Compliance', 'healthcare', 100, 'percent', 'critical', true, 'Patient health records must be stored within Nigeria', 'NHIA Act and FMOH Data Policy'),
('Solvency Ratio Minimum', 'insurance', 150, 'percent', 'critical', true, 'Minimum solvency ratio for insurance companies', 'NAICOM Insurance Act 2003'),
('Open Banking Consent Validity', 'fintech', 90, 'days', 'warning', true, 'Maximum validity period for open banking consent without renewal', 'CBN Open Banking Policy 2021'),
('Grid Frequency Deviation', 'energy', 0.5, 'hz', 'critical', true, 'Maximum acceptable deviation from 50Hz grid frequency', 'NERC Grid Code 2023'),
('ROPA Review Frequency', 'all', 365, 'days', 'warning', true, 'Maximum days between ROPA (Record of Processing Activities) reviews', 'NDPA 2023 Section 29'),
('Consent Withdrawal Processing', 'all', 24, 'hours', 'warning', true, 'Maximum time to process consent withdrawal requests', 'NDPA 2023 Section 31'),
('Cross-Border Transfer Approval', 'all', 30, 'days', 'warning', true, 'Maximum time for NDPC to approve cross-border data transfer requests', 'NDPA 2023 Section 43');
